class SessionRepository {
  db;
  constructor(db) {
    this.db = db;
  }
  async findById(id) {
    const result = await this.db.select().from(sessions).where(eq(sessions.id, id)).limit(1);
    return result[0] || null;
  }
  async findByJTI(jti) {
    const result = await this.db.select().from(sessions).where(eq(sessions.jti, jti)).limit(1);
    return result[0] || null;
  }
  async create(data) {
    const result = await this.db.insert(sessions).values(data).returning();
    return result[0];
  }
  async revoke(id) {
    await this.db.update(sessions).set({ isRevoked: 1 }).where(eq(sessions.id, id)).run();
  }
  async revokeAllByUserId(userId) {
    await this.db.update(sessions).set({ isRevoked: 1 }).where(eq(sessions.userId, userId)).run();
  }
  async listByUserId(userId) {
    return await this.db.select().from(sessions).where(eq(sessions.userId, userId)).orderBy(sql`${sessions.createdAt} DESC`).all();
  }
  async countActiveByUserId(userId) {
    const countResult = await this.db.select({ count: sql`count(*)` }).from(sessions).where(and(eq(sessions.userId, userId), eq(sessions.isRevoked, 0)));
    return countResult[0]?.count ?? 0;
  }
}

