// src/errors/code.ts
var CodeSuccess = 0;
var CodeParamInvalid = 1001;
var CodeUnauthorized = 1002;
var CodeForbidden = 1003;
var CodeUserNotFound = 2001;
var CodeUserExists = 2002;
var CodePasswordWrong = 2003;
var CodeCategoryNotFound = 3001;
var CodeItemNotFound = 4001;
var CodeInternalError = 5001;
var CodeDatabaseError = 5002;

// src/errors/index.ts
class AppError extends Error {
  code;
  cause;
  constructor(code, message, cause) {
    super(message);
    this.code = code;
    this.cause = cause;
    this.name = "AppError";
  }
}

// src/utils/time.ts
function nowUTC() {
  return new Date().toISOString();
}
function formatTime(date) {
  return date.toISOString();
}
function daysUntil(target) {
  const targetDate = new Date(target).getTime();
  const now = Date.now();
  const diffMs = targetDate - now;
  return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
}

// src/service/user.ts
var import_jsonwebtoken = __toESM(require_jsonwebtoken(), 1);

class UserService {
  userRepo;
  sessionRepo;
  jwtConfig;
  sessionConfig;
  constructor(userRepo, sessionRepo, jwtConfig, sessionConfig) {
    this.userRepo = userRepo;
    this.sessionRepo = sessionRepo;
    this.jwtConfig = jwtConfig;
    this.sessionConfig = sessionConfig;
  }
  async register(req, deviceInfo, ipAddress) {
    const existingEmail = await this.userRepo.findByEmail(req.email);
    if (existingEmail) {
      throw new AppError(CodeUserExists, "\u90AE\u7BB1\u5DF2\u88AB\u6CE8\u518C");
    }
    const existingUsername = await this.userRepo.findByUsername(req.username);
    if (existingUsername) {
      throw new AppError(CodeUserExists, "\u7528\u6237\u540D\u5DF2\u88AB\u6CE8\u518C");
    }
    const hashedPassword = await Bun.password.hash(req.password, {
      algorithm: "bcrypt",
      cost: 10
    });
    const now = nowUTC();
    const user = await this.userRepo.create({
      username: req.username,
      email: req.email,
      password: hashedPassword,
      status: 1,
      createdAt: now,
      updatedAt: now
    });
    return {
      user_id: user.id,
      username: user.username,
      email: user.email,
      status: user.status,
      created_at: user.createdAt
    };
  }
  async login(req, deviceInfo, ipAddress) {
    const user = await this.userRepo.findByEmail(req.email);
    if (!user) {
      throw new AppError(CodeUserNotFound, "\u7528\u6237\u4E0D\u5B58\u5728");
    }
    if (user.status !== 1) {
      throw new AppError(CodeForbidden, "\u8D26\u6237\u5DF2\u7981\u7528");
    }
    const isMatch = await Bun.password.verify(req.password, user.password);
    if (!isMatch) {
      throw new AppError(CodePasswordWrong, "\u5BC6\u7801\u9519\u8BEF");
    }
    const activeSessions = await this.sessionRepo.countActiveByUserId(user.id);
    if (activeSessions >= this.sessionConfig.maxSessions) {
      const sessions2 = await this.sessionRepo.listByUserId(user.id);
      const oldestActive = sessions2.filter((s) => !s.isRevoked).sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())[0];
      if (oldestActive) {
        await this.sessionRepo.revoke(oldestActive.id);
      }
    }
    const jti = crypto.randomUUID();
    const now = new Date;
    const expireDate = new Date(now.getTime() + this.jwtConfig.expireHours * 60 * 60 * 1000);
    const token = import_jsonwebtoken.default.sign({
      userId: user.id,
      jti,
      iat: Math.floor(now.getTime() / 1000)
    }, this.jwtConfig.secret, { expiresIn: `${this.jwtConfig.expireHours}h` });
    await this.sessionRepo.create({
      userId: user.id,
      jti,
      deviceInfo: deviceInfo || null,
      ipAddress: ipAddress || null,
      createdAt: nowUTC(),
      expiresAt: formatTime(expireDate),
      isRevoked: 0
    });
    return {
      user_id: user.id,
      token,
      expired: formatTime(expireDate)
    };
  }
  async getInfo(userId) {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new AppError(CodeUserNotFound, "\u7528\u6237\u4E0D\u5B58\u5728");
    }
    if (user.status !== 1) {
      throw new AppError(CodeForbidden, "\u8D26\u6237\u5DF2\u7981\u7528");
    }
    return toUserVO(user);
  }
  async update(userId, req) {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new AppError(CodeUserNotFound, "\u7528\u6237\u4E0D\u5B58\u5728");
    }
    const updateData = {};
    if (req.username) {
      const existing = await this.userRepo.findByUsername(req.username);
      if (existing && existing.id !== userId) {
        throw new AppError(CodeUserExists, "\u7528\u6237\u540D\u5DF2\u88AB\u4F7F\u7528");
      }
      updateData.username = req.username;
    }
    updateData.updatedAt = nowUTC();
    const updated = await this.userRepo.update(userId, updateData);
    if (!updated) {
      throw new AppError(CodeDatabaseError, "\u66F4\u65B0\u7528\u6237\u4FE1\u606F\u5931\u8D25");
    }
    return toUserVO(updated);
  }
  async logout(userId, sessionId) {
    const session = await this.sessionRepo.findById(sessionId);
    if (!session || session.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u4F1A\u8BDD");
    }
    await this.sessionRepo.revoke(sessionId);
  }
  async getSessions(userId) {
    const sessionList = await this.sessionRepo.listByUserId(userId);
    const sessions2 = sessionList.map((s) => ({
      session_id: s.id,
      user_id: s.userId,
      device_info: s.deviceInfo,
      ip_address: s.ipAddress,
      created_at: s.createdAt,
      expires_at: s.expiresAt,
      is_revoked: s.isRevoked === 1
    }));
    return {
      sessions: sessions2,
      total: sessions2.length
    };
  }
  async revokeSession(userId, sessionId) {
    const session = await this.sessionRepo.findById(sessionId);
    if (!session) {
      throw new AppError(CodeForbidden, "\u4F1A\u8BDD\u4E0D\u5B58\u5728");
    }
    if (session.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u4F1A\u8BDD");
    }
    await this.sessionRepo.revoke(sessionId);
  }
  async forceLogout(userId) {
    await this.sessionRepo.revokeAllByUserId(userId);
  }
}

// src/model/vo/category.ts
function toCategoryVO(cat) {
  return {
    category_id: cat.id,
    user_id: cat.userId,
    name: cat.name,
    color: cat.color,
    icon: cat.icon,
    sort_order: cat.sortOrder,
    created_at: cat.createdAt
  };
}

// src/service/category.ts
class CategoryService {
  categoryRepo;
  itemRepo;
  constructor(categoryRepo, itemRepo) {
    this.categoryRepo = categoryRepo;
    this.itemRepo = itemRepo;
  }
  async create(userId, req) {
    const existing = await this.categoryRepo.findByUserIdAndName(userId, req.name);
    if (existing) {
      throw new AppError(CodeUserExists, "\u5206\u7C7B\u540D\u79F0\u5DF2\u5B58\u5728");
    }
    const now = nowUTC();
    const category = await this.categoryRepo.create({
      userId,
      name: req.name,
      color: req.color || null,
      icon: req.icon || null,
      sortOrder: req.sort_order ?? 0,
      createdAt: now,
      updatedAt: now
    });
    return toCategoryVO(category);
  }
  async list(userId, params) {
    const { items: items2, total } = await this.categoryRepo.list({
      userId,
      ...params
    });
    return {
      list: items2.map(toCategoryVO),
      total,
      page: params.page
    };
  }
  async update(userId, req) {
    const category = await this.categoryRepo.findById(req.category_id);
    if (!category) {
      throw new AppError(CodeCategoryNotFound, "\u5206\u7C7B\u4E0D\u5B58\u5728");
    }
    if (category.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u5206\u7C7B");
    }
    if (req.name && req.name !== category.name) {
      const existing = await this.categoryRepo.findByUserIdAndName(userId, req.name);
      if (existing && existing.id !== req.category_id) {
        throw new AppError(CodeUserExists, "\u5206\u7C7B\u540D\u79F0\u5DF2\u5B58\u5728");
      }
    }
    const updateData = {};
    if (req.name !== undefined)
      updateData.name = req.name;
    if (req.color !== undefined)
      updateData.color = req.color;
    if (req.icon !== undefined)
      updateData.icon = req.icon;
    if (req.sort_order !== undefined)
      updateData.sortOrder = req.sort_order;
    updateData.updatedAt = nowUTC();
    const updated = await this.categoryRepo.update(req.category_id, updateData);
    if (!updated) {
      throw new AppError(CodeDatabaseError, "\u66F4\u65B0\u5206\u7C7B\u5931\u8D25");
    }
    return toCategoryVO(updated);
  }
  async delete(userId, categoryId) {
    const category = await this.categoryRepo.findById(categoryId);
    if (!category) {
      throw new AppError(CodeCategoryNotFound, "\u5206\u7C7B\u4E0D\u5B58\u5728");
    }
    if (category.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u5206\u7C7B");
    }
    await this.itemRepo.deleteByCategoryId(categoryId);
    await this.categoryRepo.delete(categoryId);
  }
}

