// src/service/item.ts
class ItemService {
  itemRepo;
  constructor(itemRepo) {
    this.itemRepo = itemRepo;
  }
  async create(userId, req) {
    const now = nowUTC();
    const status = new Date(req.expired_at).getTime() < Date.now() ? 2 : 1;
    const item = await this.itemRepo.create({
      userId,
      categoryId: req.category_id,
      name: req.name,
      description: req.description || null,
      quantity: req.quantity ?? 1,
      unit: req.unit || null,
      expiredAt: req.expired_at,
      remindDays: req.remind_days ?? 3,
      status,
      createdAt: now,
      updatedAt: now
    });
    return toItemVO(item);
  }
  async list(userId, params) {
    const { items: items2, total } = await this.itemRepo.list({
      userId,
      ...params
    });
    return {
      list: items2.map(toItemVO),
      total,
      page: params.page
    };
  }
  async detail(userId, itemId) {
    const item = await this.itemRepo.findById(itemId);
    if (!item) {
      throw new AppError(CodeItemNotFound, "\u7269\u54C1\u4E0D\u5B58\u5728");
    }
    if (item.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u67E5\u770B\u6B64\u7269\u54C1");
    }
    return toItemVO(item);
  }
  async update(userId, req) {
    const item = await this.itemRepo.findById(req.item_id);
    if (!item) {
      throw new AppError(CodeItemNotFound, "\u7269\u54C1\u4E0D\u5B58\u5728");
    }
    if (item.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u7269\u54C1");
    }
    const updateData = {};
    if (req.category_id !== undefined)
      updateData.categoryId = req.category_id;
    if (req.name !== undefined)
      updateData.name = req.name;
    if (req.description !== undefined)
      updateData.description = req.description;
    if (req.quantity !== undefined)
      updateData.quantity = req.quantity;
    if (req.unit !== undefined)
      updateData.unit = req.unit;
    if (req.expired_at !== undefined)
      updateData.expiredAt = req.expired_at;
    if (req.remind_days !== undefined)
      updateData.remindDays = req.remind_days;
    updateData.updatedAt = nowUTC();
    if (req.expired_at) {
      updateData.status = new Date(req.expired_at).getTime() < Date.now() ? 2 : 1;
    }
    const updated = await this.itemRepo.update(req.item_id, updateData);
    if (!updated) {
      throw new AppError(CodeDatabaseError, "\u66F4\u65B0\u7269\u54C1\u5931\u8D25");
    }
    return toItemVO(updated);
  }
  async delete(userId, itemId) {
    const item = await this.itemRepo.findById(itemId);
    if (!item) {
      throw new AppError(CodeItemNotFound, "\u7269\u54C1\u4E0D\u5B58\u5728");
    }
    if (item.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u5220\u9664\u6B64\u7269\u54C1");
    }
    await this.itemRepo.delete(itemId);
  }
  async getExpiring(userId, days) {
    const items2 = await this.itemRepo.getExpiringItems(userId, days);
    return items2.map((item) => toExpiringItemVO(item, daysUntil(item.expiredAt)));
  }
  async getStats(userId) {
    const stats = await this.itemRepo.getStats(userId);
    return toItemStatsVO(stats);
  }
  async markUsed(userId, itemId) {
    const item = await this.itemRepo.findById(itemId);
    if (!item) {
      throw new AppError(CodeItemNotFound, "\u7269\u54C1\u4E0D\u5B58\u5728");
    }
    if (item.userId !== userId) {
      throw new AppError(CodeForbidden, "\u65E0\u6743\u64CD\u4F5C\u6B64\u7269\u54C1");
    }
    const now = nowUTC();
    const updated = await this.itemRepo.update(itemId, {
      status: 3,
      updatedAt: now
    });
    if (!updated) {
      throw new AppError(CodeDatabaseError, "\u66F4\u65B0\u7269\u54C1\u72B6\u6001\u5931\u8D25");
    }
    return toItemVO(updated);
  }
}

// src/service/item_expiration.ts
var ItemStatus = {
  Normal: 1,
  Expired: 2,
  Used: 3
};

class ItemExpirationService {
  itemRepo;
  config;
  logger;
  intervalId = null;
  running = false;
  constructor(itemRepo, config, logger) {
    this.itemRepo = itemRepo;
    this.config = config;
    this.logger = logger;
    if (this.config.intervalSec <= 0) {
      this.config.intervalSec = 3600;
    }
    if (this.config.batchSize <= 0) {
      this.config.batchSize = 100;
    }
  }
  start() {
    if (this.running) {
      this.logger.warn("[Expiration] \u8FC7\u671F\u68C0\u67E5\u4EFB\u52A1\u5DF2\u5728\u8FD0\u884C\u4E2D");
      return;
    }
    if (!this.config.enabled) {
      this.logger.info("[Expiration] \u8FC7\u671F\u68C0\u67E5\u4EFB\u52A1\u5DF2\u7981\u7528");
      return;
    }
    this.running = true;
    this.checkExpiredItems().catch((err) => {
      this.logger.error({ err }, "[Expiration] \u542F\u52A8\u65F6\u6267\u884C\u8FC7\u671F\u68C0\u67E5\u5931\u8D25");
    });
    this.intervalId = setInterval(() => {
      this.checkExpiredItems().catch((err) => {
        this.logger.error({ err }, "[Expiration] \u5B9A\u65F6\u8FC7\u671F\u68C0\u67E5\u5931\u8D25");
      });
    }, this.config.intervalSec * 1000);
    this.logger.info({
      intervalSec: this.config.intervalSec,
      batchSize: this.config.batchSize
    }, "[Expiration] \u8FC7\u671F\u68C0\u67E5\u4EFB\u52A1\u5DF2\u542F\u52A8");
  }
  async checkExpiredItems() {
    const expiredItems = await this.itemRepo.getExpiredItems(this.config.batchSize);
    if (expiredItems.length === 0) {
      return 0;
    }
    const ids = expiredItems.map((item) => item.id);
    await this.itemRepo.batchUpdateStatus(ids, ItemStatus.Expired);
    this.logger.info({ updatedCount: expiredItems.length }, "[Expiration] \u8FC7\u671F\u68C0\u67E5\u5B8C\u6210");
    return expiredItems.length;
  }
  stop() {
    if (!this.running) {
      return;
    }
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.running = false;
    this.logger.info("[Expiration] \u8FC7\u671F\u68C0\u67E5\u4EFB\u52A1\u5DF2\u505C\u6B62");
  }
}

// src/utils/response.ts
function success(c, data) {
  return c.json({
    code: CodeSuccess,
    message: "success",
    data
  });
}
function failWithCode(c, code, message) {
  return c.json({
    code,
    message,
    data: null
  });
}
function fail(c, error) {
  if (error instanceof AppError) {
    return c.json({
      code: error.code,
      message: error.message,
      data: null
    });
  }
  console.error("Unhandled error:", error);
  return c.json({
    code: CodeInternalError,
    message: "\u5185\u90E8\u9519\u8BEF",
    data: null
  });
}

